-- STEP 1: Create brands table
CREATE TABLE IF NOT EXISTS brands (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  name TEXT UNIQUE NOT NULL,
  description TEXT,
  location TEXT,
  known_for TEXT,
  product_types TEXT,
  talking_points TEXT[],
  is_active BOOLEAN DEFAULT true,
  featured_week DATE,
  created_at TIMESTAMPTZ DEFAULT now()
);

ALTER TABLE brands ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Allow read for authenticated" ON brands
  FOR SELECT TO authenticated USING (true);

CREATE POLICY "Allow insert for authenticated" ON brands
  FOR INSERT TO authenticated WITH CHECK (true);

CREATE POLICY "Allow update for authenticated" ON brands
  FOR UPDATE TO authenticated USING (true);

-- STEP 2: Seed all brands (names only for most, details for researched ones)
ON CONFLICT (name) DO UPDATE SET
  description = COALESCE(EXCLUDED.description, brands.description),
  location = COALESCE(EXCLUDED.location, brands.location),
  known_for = COALESCE(EXCLUDED.known_for, brands.known_for),
  product_types = COALESCE(EXCLUDED.product_types, brands.product_types),
  talking_points = COALESCE(EXCLUDED.talking_points, brands.talking_points);
